parameters.jsCode:
// Define engagement actions to take
const recentPosts = $('Fetch Recent Published Posts').all() || [];
const hour = new Date().getHours();

const engagementTasks = {
  check_comments: {
    description: 'Verifier les commentaires non repondus sur nos posts recents',
    posts: recentPosts.map(p => ({ id: p.json.id, platform: p.json.platform, title: p.json.title }))
  },
  check_mentions: {
    description: 'Verifier les mentions de la marque',
    platforms: ['meta', 'tiktok', 'linkedin']
  },
  proactive_engage: {
    description: 'Engagement proactif sur des posts pertinents de notre industrie',
    keywords: ($env.ENGAGEMENT_KEYWORDS || 'marketing digital,automatisation,IA marketing').split(',')
  },
  session_time: hour < 12 ? 'morning' : (hour < 16 ? 'afternoon' : 'evening')
};

return { json: engagementTasks };

