parameters.jsCode:
const aiResponse = $input.item.json.message.content;
let plan;
try {
  plan = JSON.parse(aiResponse);
} catch (e) {
  plan = { error: 'Parse failed' };
}

return {
  json: {
    report_type: 'engagement_session',
    session_time: new Date().toISOString(),
    agent_id: 'community-manager',
    workflow_id: 'WF-COMMUNITY-ENGAGE',
    plan,
    total_actions: plan.engagement_actions?.length || 0
  }
};
